// Unit 1 homework: quadratic functions (graphing, transformations, characteristics,
// intercept form, writing equations) plus the two unit reviews. Generated by
// src/quadratics.js and src/lines.js; `check`/`exp` hold the answer key so
// scripts/verify.mjs and scripts/verify_sympy.py can confirm it.
import { quadProblem, stdToVertex, stdToIntercept, writeVertexPoint, writeZerosPoint, qFn, quad, specLatex } from '../../quadratics.js'
import { absProblem, absWrite, graphLine, pwGraphProblem, pwWriteProblem, writeLine } from '../../lines.js'

const R = String.raw
const hand = (prompt, steps, answer, extra = {}) => ({ type: 'steps', prompt, steps, answer, ...extra })
const withStep = (p, step) => ({ ...p, steps: [...p.steps, step] })
const mc = (problem, choice, choices) => ({ ...problem, choice, choices: choices.map((t, i) => ['ABCDEF'[i], t]) })
const fr = (n, d) => [n, d]
// quadProblem with the worksheet prompt (y = …) and the key's vertex (and zeros) for verification
const qp = (spec, ask, vertex, extra = {}) => quadProblem(extra.prompt ?? `y = ${specLatex(spec)}`, spec, ask, { exp: { vertex, zeros: extra.zeros }, window: extra.window })
const ALL = ['vertex', 'axis', 'yint', 'graph', 'domain', 'range', 'incdec']
const ln = (m, b, lo, hi, loIn = false, hiIn = false) => ({ m, b, lo, hi, loIn, hiIn })
const cst = (c, lo, hi, loIn = false, hiIn = false) => ({ c, lo, hi, loIn, hiIn })
const av = (a, h, k, lo, hi, loIn = false, hiIn = false) => ({ abs: [a, h, k], lo, hi, loIn, hiIn })
const si = (m, b) => `y - (${m}*x + ${b})`
const std = (A, B, C) => `${A}*x + ${B}*y - (${C})`
const interval = (prompt, answer, why) => hand(prompt, [why], answer)

// HW #1 10–15: the six graphs, drawn from the functions the key matches them to.
const MATCH_FNS = [R`y = -x^2 - 3x`, R`y = x^2 - 3x`, R`y = x^2 + 3x`, R`y = -x^2 + 3`, R`y = x^2 - 3`, R`y = -x^2 + 3x`]
const MATCH_STD = [[-1, -3, 0], [1, -3, 0], [1, 3, 0], [-1, 0, 3], [1, 0, -3], [-1, 3, 0]]
const matchGraph = (letter, why) => {
  const i = 'ABCDEF'.indexOf(letter)
  return mc({
    type: 'steps', prompt: R`\text{Which function matches this graph?}`,
    given: { window: [-5, 5, -5, 5], items: [{ kind: 'fn', f: qFn(quad(...MATCH_STD[i])) }] },
    steps: [why, R`That is $${MATCH_FNS[i]}$.`],
    answer: MATCH_FNS[i],
  }, letter, MATCH_FNS)
}

